===SPEC===
// Spec helpers for `FrameAddress` are shared with the `phys` sibling module: a frame's abstract
// state is the physical address (`int`), its frame number is `self@ / spec_page_size()`, and its
// base address is `frame_index * spec_page_size()`.
use crate::hal::mem::types::address::phys::{
    spec_frame_number,
    spec_from_number,
    spec_frame_raw_value,
    spec_max_frame_number,
};

// The former `assume_specification` for `<PhysicalAddress as ::sys::mm::Address>::from_raw_value`
// was removed: it supplied a trusted, unverified contract to a kernel-internal (intra-crate)
// callee that is not sanctioned in `tcb-allowed.md`. Its sole consumer, `FrameAddress::from_raw_value`,
// is instead carried as a TCB-listed `#[verus_verify(external_body)]` (see `frame.rs`), so no
// intra-crate trust hole remains here.
===PROOF===
use vstd::arithmetic::div_mod::{
    lemma_fundamental_div_mod,
    lemma_mod_multiples_basic,
};

verus! {

// =================================================================================================
// Proof obligations for `FrameAddress`'s frame-number conversions.
//
// The facts below are elementary divisibility properties of `spec_page_size()`, which is the
// `#[verus_verify]` constant `arch::mem::PAGE_SIZE == 4096` and therefore strictly positive.
// =================================================================================================

// `frame_index * PAGE_SIZE` is a multiple of `PAGE_SIZE`, hence page-aligned. Used by
// `from_frame_number` to discharge `PageAligned::from_address`'s alignment success condition.
pub proof fn lemma_frame_base_aligned(frame: FrameNumber)
    ensures
        spec_from_number(spec_frame_raw_value(frame)) % spec_page_size() == 0,
{
    // `spec_page_size()` is the transparent constant `PAGE_SIZE == 4096 > 0`.
    assert(spec_page_size() == 4096);
    // `spec_from_number(spec_frame_raw_value(frame)) == frame@ * spec_page_size()`, a multiple of
    // `spec_page_size()`, so its remainder mod `spec_page_size()` is zero.
    lemma_mod_multiples_basic(spec_frame_raw_value(frame), spec_page_size());
}

// For a page-aligned address, dividing by `PAGE_SIZE` then multiplying recovers the address
// exactly. Used by `into_frame_number` to relate the recovered frame number back to `self@`.
pub proof fn lemma_aligned_div_mul(addr: int)
    requires
        addr % spec_page_size() == 0,
    ensures
        spec_from_number(spec_frame_number(addr)) == addr,
{
    // `spec_page_size()` is the transparent constant `PAGE_SIZE == 4096 > 0`.
    assert(spec_page_size() == 4096);
    // `addr == s * (addr / s) + (addr % s)` with `addr % s == 0`, so `(addr / s) * s == addr`.
    lemma_fundamental_div_mod(addr, spec_page_size());
}

} // verus!

