     fn fmt(&self, f: &mut core::fmt::Formatter) -> core::fmt::Result {
         write!(f, "FrameAddress({:#010x})", self.into_raw_value())
     }
 }

 impl PartialEq for FrameAddress {
     fn eq(&self, other: &Self) -> bool {
         self.0 == other.0
     }
 }

